	@ParameterizedTest
	@EnumSource(PullRestoreTestMode.class)
	void nestedOptionalMatchesWholeRowRestoreAndClosesOnDemand(PullRestoreTestMode mode) {
		Kernel ir = nestedOptional();
		Rows plan = optionalRows();
		LmdbNativeKernelInterpreter execution = LmdbNativeKernelInterpreter.forRows(ir, mode);
		assertNotNull(execution);
		try {
			execution.bind(optionalContext(plan));
			PullRestoreSite lexical = execution.pullRestoreSites().get(1);
			PullRestoreSite rightGroup = lexical.children().get(1).get(1);
			PullRestoreSite child = rightGroup.children().getFirst().getFirst();
			if (mode == PullRestoreTestMode.VERIFY) {
				assertTrue(lexical.restoresAfterOpen(), "opening the lexical frame clears its problem columns");
				assertFalse(child.restoresAfterOpen(), "opening a delegated cursor leaves its frame intact");
				assertTrue(writes(child, X), "correlated PlanRows overwrites its hidden caller column");
				assertTrue(writes(child, PAYLOAD), "column 63 must be restored");
				assertTrue(child.restoredColumns().length < ir.columnCount);
			}
			assertEquals(OPTIONAL_ROWS, drain(ir, execution));
		} finally {
			execution.close();
		}
		assertEquals(List.of(List.of(-1L, 10L), List.of(-1L, 30L), List.of(-1L, 40L)), plan.activations);
		assertEquals(3, plan.cursorCloses);

		Rows early = optionalRows();
		try {
			execution.bind(optionalContext(early));
			long[] row = new long[ir.stride()];
			assertEquals(1, execution.fill(row, 1));
			assertEquals(OPTIONAL_ROWS.getFirst(), Arrays.toString(row));
			assertEquals(1, early.cursorFills, "one requested row must not advance to later right rows");
		} finally {
			execution.close();
		}
		assertEquals(List.of(List.of(-1L, 10L)), early.activations);
		assertEquals(1, early.cursorCloses);
	}

	@ParameterizedTest
	@EnumSource(PullRestoreTestMode.class)
	void childThatDoesNotWriteTheHiddenColumnStillRestoresIt(PullRestoreTestMode mode) {
		PlanRows child = new PlanRows(0, new int[] { PAYLOAD },
				new Operand[] { Operand.col(X), Operand.col(CASE) });
		LexicalFrameLeftJoin optional = new LexicalFrameLeftJoin(
				List.of(new BindAlias(Operand.constant(1), CASE)),
				List.of(new LeftGroup(List.of(child)), new BindAlias(Operand.col(X), OBSERVED_X)),
				new int[] { X });
		Kernel ir = new Kernel(64, List.of(new BindAlias(Operand.constant(0), X), optional,
				new BindAlias(Operand.col(CASE), X)),
				new Emit(new int[] { X, OBSERVED_X, PAYLOAD }, false, OutputMods.none()));
		Rows plan = new Rows(inputs -> new long[][] { { 101 }, { 102 } });
		LmdbNativeKernelInterpreter execution = LmdbNativeKernelInterpreter.forRows(ir, mode);
		assertNotNull(execution);
		try {
			execution.bind(optionalContext(plan));
			PullRestoreSite lexical = execution.pullRestoreSites().get(1);
			PullRestoreSite rightGroup = lexical.children().get(1).getFirst();
			PullRestoreSite planSite = rightGroup.children().getFirst().getFirst();
			if (mode == PullRestoreTestMode.VERIFY) {
				assertTrue(writes(planSite, X), "a resumed child must reestablish the hidden caller column");
				assertTrue(planSite.restoredColumns().length < ir.columnCount);
			}
			assertEquals(List.of("[20, -1, 101]", "[20, -1, 102]"), drain(ir, execution));
		} finally {
			execution.close();
		}
		assertEquals(List.of(List.of(-1L, 20L)), plan.activations);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void distinguishesSparsePhysicalOutputsFromAWholeFrame(boolean dense) {
		int[] columns = dense ? IntStream.range(0, 64).toArray() : new int[] { X, PAYLOAD };
		PlanRows planRows = new PlanRows(0, columns, new Operand[] { Operand.col(X), Operand.constant(0) });
		Kernel ir = new Kernel(64, List.of(new BindAlias(Operand.constant(0), X), planRows),
				new Emit(new int[] { X, PAYLOAD }, false, OutputMods.none()));
		long[] first = IntStream.range(0, columns.length).mapToLong(i -> 100L + columns[i]).toArray();
		long[] second = IntStream.range(0, columns.length).mapToLong(i -> 200L + columns[i]).toArray();
		Rows plan = new Rows(inputs -> new long[][] { first, second });
		LmdbNativeKernelInterpreter execution = LmdbNativeKernelInterpreter.forRows(ir, PullRestoreTestMode.VERIFY);
		assertNotNull(execution);
		try {
			execution.bind(optionalContext(plan));
			assertArrayEquals(columns, execution.pullRestoreSites().get(1).restoredColumns());
			assertEquals(List.of("[102, 163]", "[202, 263]"), drain(ir, execution));
		} finally {
			execution.close();
		}
	}

